package com.shikshasetu.ai;
import com.fasterxml.jackson.databind.ObjectMapper;import com.shikshasetu.model.AiAssessment;import com.shikshasetu.repo.AiAssessmentRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import weka.core.*;import java.time.Instant;import java.util.*;
@Service public class AiPredictionService {
 private final AiFeatureService features;private final AiModelRuntime runtime;private final AiAssessmentRepository repo;private final ObjectMapper mapper;
 public AiPredictionService(AiFeatureService f,AiModelRuntime r,AiAssessmentRepository a,ObjectMapper m){features=f;runtime=r;repo=a;mapper=m;}
 public List<com.shikshasetu.model.AiAssessment> history(Long id){return repo.findByStudentIdOrderByAssessedAtDesc(id);}
 @Transactional public AiAssessmentResponse assess(Long id){AiFeatureVector v=features.forStudent(id);ModelBundle b=runtime.current().orElseThrow(()->new IllegalStateException("ML model not trained. Upload approved labelled longitudinal CSV to POST /api/ai/model/train."));try{double p;synchronized(b.getClassifier()){double[] values=Arrays.copyOf(v.toArray(),9);values[8]=Instance.missingValue();Instance in=new DenseInstance(1,values);in.setDataset(b.getHeader());p=b.getClassifier().distributionForInstance(in)[1];}String band=p>=.65?"HIGH":p>=.35?"MEDIUM":"LOW";List<String> signals=signals(v);List<AiAssessmentResponse.SupportSuggestion> suggestions=suggestions(v);List<String>warnings=new ArrayList<>();if(v.recentMarkDrop()==null||v.repeatedLowResults()==null)warnings.add("No usable dated subject-mark pair was found; trend features are missing, not assumed to be zero.");if(v.consecutiveAbsences()==null)warnings.add("No consecutive-absence streak was recorded; this feature is missing, not assumed to be zero.");AiAssessment saved=repo.save(new AiAssessment(id,p,band,b.getModelVersion(),mapper.writeValueAsString(v.asMap()),mapper.writeValueAsString(signals),mapper.writeValueAsString(suggestions)));return new AiAssessmentResponse(saved.getId(),id,"TRAINED_PROTOTYPE",b.getModelVersion(),Math.round(p*10000)/10000.0,band,v.asMap(),signals,suggestions,true,warnings,"This model estimates the defined next-period academic deterioration outcome. It does not identify causes, diagnose a student or decide support. Review the context with the student and mentor.",Instant.now());}catch(Exception e){throw new IllegalStateException("AI assessment failed: "+e.getMessage(),e);}}
 private List<String> signals(AiFeatureVector v){List<String>s=new ArrayList<>();if(v.attendancePercent()!=null&&v.attendancePercent()<75)s.add("Attendance below 75%; ask about barriers without blame.");if(v.internalMarksPercent()!=null&&v.internalMarksPercent()<55)s.add("Internal marks below 55%; review subject results and learning gaps.");if(v.assignmentCompletionPercent()!=null&&v.assignmentCompletionPercent()<75)s.add("Assignment completion below 75%; consider smaller milestones.");if(v.recentMarkDrop()!=null&&v.recentMarkDrop()>=10)s.add("A subject mark decline of at least 10 percentage points is recorded.");if(v.repeatedLowResults()!=null&&v.repeatedLowResults()>0)s.add("Repeated low results are recorded in "+(int)v.repeatedLowResults()+" subject(s).");if(v.consecutiveAbsences()!=null&&v.consecutiveAbsences()>=3)s.add(v.consecutiveAbsences()+" consecutive absences are recorded; check in supportively.");if(s.isEmpty())s.add("No configured early-warning threshold crossed in the available academic fields.");return s;}
 private List<AiAssessmentResponse.SupportSuggestion> suggestions(AiFeatureVector v){List<AiAssessmentResponse.SupportSuggestion>s=new ArrayList<>();if((v.internalMarksPercent()!=null&&v.internalMarksPercent()<55)||(v.recentMarkDrop()!=null&&v.recentMarkDrop()>=10)||(v.repeatedLowResults()!=null&&v.repeatedLowResults()>0))s.add(new AiAssessmentResponse.SupportSuggestion("Subject-specific learning support","Marks or dated subject results suggest a learning gap may need review.","Ask which concepts feel difficult and agree a short revision plan.","Complete two focused practice sessions and review one topic with a mentor this week.","Teacher-approved notes, worked examples and subject practice"));if((v.attendancePercent()!=null&&v.attendancePercent()<75)||(v.consecutiveAbsences()!=null&&v.consecutiveAbsences()>=3))s.add(new AiAssessmentResponse.SupportSuggestion("Attendance support conversation","Attendance signals warrant understanding practical barriers.","Discuss timetable, transport, health or other barriers privately.","Agree a manageable attendance/check-in goal for the next five study days.","Mentor check-in and institution support services"));if(v.assignmentCompletionPercent()!=null&&v.assignmentCompletionPercent()<75)s.add(new AiAssessmentResponse.SupportSuggestion("Assignment catch-up","Completion rate may reflect workload, access or concept difficulties.","Break pending work into small milestones and ask what support is needed.","Finish one agreed priority task before the next check-in.","Course LMS, rubric and mentor-approved examples"));if(s.isEmpty())s.add(new AiAssessmentResponse.SupportSuggestion("Strength-based progress plan","No configured threshold crossed in available profile fields.","Ask what is working well and choose an optional stretch goal together.","Choose one student-owned learning goal and review it next week.","Course enrichment resources"));return s;}
}
